// Cross-language check: the JS PMCH-v1 reference (src/lib/canonicalHash.ts) must
// reproduce the canonical strings + keccak hashes generated by the Python
// reference (backend/app/manifests.py), proving a manifest hash locked on-chain
// is verifiable from the published JSON in either language.
//
// Run:  node scripts/canonical-hash-check.mjs
// (Node >= 23.6 strips TS types natively, so importing the .ts module works.)

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { keccak256, toBytes } from "viem";
import { canonicalSerialize, computeManifestHash } from "../src/lib/canonicalHash.ts";

const here = dirname(fileURLToPath(import.meta.url));
const fixturePath = resolve(here, "../../backend/tests/fixtures/canonical_hash_vectors.json");
const fixture = JSON.parse(readFileSync(fixturePath, "utf-8"));

let failures = 0;
const fail = (msg) => {
  failures++;
  console.error(`  ✗ ${msg}`);
};

console.log(`serialize vectors (${fixture.serialize.length}):`);
for (const e of fixture.serialize) {
  const canonical = canonicalSerialize(e.value);
  if (canonical !== e.canonical) {
    fail(`${e.name}: canonical mismatch\n      js: ${canonical}\n      py: ${e.canonical}`);
    continue;
  }
  const hash = keccak256(toBytes(canonical));
  if (hash !== e.keccak) {
    fail(`${e.name}: keccak mismatch\n      js: ${hash}\n      py: ${e.keccak}`);
    continue;
  }
  console.log(`  ✓ ${e.name}`);
}

console.log(`manifest vectors (${fixture.manifest.length}):`);
for (const e of fixture.manifest) {
  const hash = computeManifestHash(e.manifest);
  if (hash !== e.hash) {
    fail(`${e.name}: manifest hash mismatch\n      js: ${hash}\n      py: ${e.hash}`);
    continue;
  }
  console.log(`  ✓ ${e.name}`);
}

if (failures > 0) {
  console.error(`\nFAILED: ${failures} mismatch(es) — JS and Python canonical forms diverge.`);
  process.exit(1);
}
console.log("\nOK: JS reference matches the Python golden vectors byte-for-byte.");
